(function(root){
function nearestStation(engine,train){const d=engine.lines[train.line].distances;let idx=0;for(let i=1;i<d.length;i++)if(Math.abs(d[i]-train.position)<Math.abs(d[idx]-train.position))idx=i;return{index:idx,distance:Math.abs(d[idx]-train.position)};}
function doorCommand(engine,open){const op=engine.operator;if(!op)return'No hay tren bajo control manual.';const t=engine.trains.find(t=>t.id===op.trainId);if(op.platformAdjust)return'Espera a terminar el ajuste o cancélalo antes de operar las puertas.';if(open){const n=nearestStation(engine,t);if(t.speed>.08)return'Detén el tren antes de abrir las puertas.';if(n.distance>2.5)return'Alinea el tren con la parada de estación (±2.5 m en este escenario).';if(engine.emergency||!engine.power[t.line])return'Restablece energía y libera la emergencia para el mando de puertas.';if(op.phase!=='closed')return'Las puertas ya están abiertas o hay un cierre en curso.';op.phase='open';op.doorsLocked=false;op.easyTargetSpeed=0;op.throttle=0;op.brake=1;t.target=n.index;t.stopDwell=engine.stationDwell(t);t.wait=t.stopDwell;t.speed=0;t.state='Abriendo puertas · operador';t.stops++;return'Abriendo puertas en '+engine.lines[t.line].stations[n.index].nombre+'.';}
 if(op.phase!=='open')return'Las puertas ya están cerradas o en cierre.';op.phase='warning';t.wait=6.5;return'Advertencia de cierre: 5 segundos; después se cierran las puertas.';}
function stepManual(engine,t,dt){const op=engine.operator,line=engine.lines[t.line],power=engine.power[t.line];root.MetroCab?.beforeStep(engine,t,dt);if(root.MetroPlatformAdjust?.step(engine,t,dt))return;
 if(op.phase==='open'){t.speed=0;if(engine.emergency||!power){t.state='Puertas detenidas · interbloqueo';return;}t.wait=Math.max(4.6,t.wait-dt);t.state='Puertas abiertas · operador';return;}
 if(op.phase==='warning'||op.phase==='closing'){t.speed=0;if(engine.emergency||!power){t.state='Cierre detenido · interbloqueo';return;}t.wait=Math.max(0,t.wait-dt);op.phase=t.wait>1.5?'warning':'closing';t.state=op.phase==='warning'?'Advertencia de cierre · operador':'Cerrando puertas · operador';if(!t.wait){engine.exchange(t);if(op.systemsEnabled&&((t.target===line.stations.length-1&&t.direction===1)||(t.target===0&&t.direction===-1))){op.needsCabChange=true;op.throttle=0;op.brake=1;op.message='Terminal: selecciona inversor neutro y cambia de cabina.';}else{if(t.target===line.stations.length-1)t.direction=-1;if(t.target===0)t.direction=1;t.target+=t.direction;}op.phase='closed';op.doorsLocked=!op.doorFault;}return;}
 let brake=Math.max(0,Math.min(1,op.brake)),throttle=Math.max(0,Math.min(1,op.throttle));if(engine.emergency){brake=1;throttle=0;}if(!power)throttle=0;
 let safety=false;if(t.line===1&&op.doorFault){op.doorsLocked=false;brake=1;throttle=0;op.throttle=0;op.brake=1;op.assisted=false;op.message="Supervisión de puertas perdida: tracción bloqueada y freno de servicio · referencia CBTC L1, pp. 72–73.";}for(const o of engine.trains){const gap=(o.position-t.position)*t.direction*(op.systemsEnabled?op.inverter:1);if(o!==t&&o.line===t.line&&o.direction===t.direction&&gap>0&&gap<180+t.speed*t.speed/2.4){brake=1;throttle=0;safety=true;}}
 const b=engine.emergency?2:(t.line===1?1.8:1.2),a=t.line===1?1.4:1;const cap=(op.systemsEnabled&&op.inverter===-1?5:engine.speedLimit(t))/3.6;if(t.speed>cap){brake=Math.max(brake,.65);throttle=0;}t.speed=Math.max(0,Math.min(Math.max(cap,t.speed),t.speed+(brake>0?-b*brake:power?a*engine.accelerationFactor(t)*throttle:-.2)*dt));
 t.position=Math.max(0,Math.min(line.total,t.position+t.direction*(op.systemsEnabled?op.inverter:1)*t.speed*dt));if(t.position===0||t.position===line.total){t.speed=0;if(op.systemsEnabled&&op.inverter===-1){op.reverseAuthorized=false;op.throttle=0;op.brake=1;}}
 t.wait=0;t.state=engine.emergency?'Freno de emergencia':safety?'Frenado por separación':brake>0?'Frenando · operador':throttle>0&&power?'Tracción · operador':'Marcha por inercia · operador';
 if((!op.systemsEnabled||op.inverter===1)&&t.direction*(t.position-line.distances[t.target])>3){op.missed++;op.message='Se pasó la parada de '+line.stations[t.target].nombre+'.';t.target=Math.max(0,Math.min(line.stations.length-1,t.target+t.direction));}
}
root.MetroManual={nearestStation,doorCommand,stepManual};
})(typeof window!=='undefined'?window:globalThis);
